import 'dart:math';import 'package:flutter/foundation.dart';class OfflineAIService {  final Random _random = Random();  final Map<String, List<String>> _autoReplies = {    'greeting': [      'Hey!',      'Hi there!',      'Hello!',      'Hey, how are you?',      'Hi! What\'s up?'    ],    'question': [      'Let me check on that.',      'I\'ll get back to you.',      'Good question!',      'I\'m looking into it.'    ],    'thanks': ['You\'re welcome!', 'No problem!', 'Happy to help!', 'Anytime!'],    'urgent': [      'On my way!',      'I\'ll be there ASAP!',      'Heading there now!',      'Coming!'    ],    'location': [      'I\'m nearby.',      'About 5 minutes out.',      'Almost there!',      'Just arrived.'    ],    'ok': ['Got it!', 'OK', 'Sounds good!', 'Alright!', 'Sure thing!'],    'affirmative': [      'Yes!',      'Absolutely!',      'Count me in!',      'Yes, please!',      'Definitely!'    ],    'negative': [      'No, thanks.',      'Not right now.',      'Maybe later.',      'I\'ll pass.'    ],    'emergency': [      'EMERGENCY! I need help!',      'SOS - sending location!',      'Need assistance ASAP!',      'HELP!'    ],  };  final Map<String, List<String>> _keywords = {    'help': ['assistance', 'support', 'aid', 'rescue', 'need'],    'location': ['where', 'location', 'address', 'nearby', 'here', 'there'],    'time': ['when', 'time', 'hour', 'minute', 'schedule', 'soon'],    'food': ['hungry', 'food', 'eat', 'meal', 'dinner', 'lunch', 'breakfast'],    'medical': [      'hurt',      'pain',      'sick',      'injury',      'doctor',      'medicine',      'hospital'    ],    'safety': ['danger', 'safe', 'warning', 'alert', 'threat', 'emergency'],    'weather': ['rain', 'weather', 'storm', 'hot', 'cold', 'temperature'],    'vehicle': ['car', 'bike', 'drive', 'gas', 'fuel', 'parking', 'route'],  };  final List<String> _summarizePhrases = [    'In summary,',    'To sum up,',    'Key points:',    'Bottom line,',    'The main idea is,',  ];  String classifyMessage(String text) {    final lower = text.toLowerCase();    if (_isUrgent(lower)) return 'urgent';    if (_isQuestion(lower)) return 'question';    if (_isGreeting(lower)) return 'greeting';    if (_isThanks(lower)) return 'thanks';    if (_isAffirmative(lower)) return 'affirmative';    if (_isNegative(lower)) return 'negative';    if (_isEmergency(lower)) return 'emergency';    return 'general';  }  bool _isUrgent(String text) {    final urgentPatterns = [      'asap',      'urgent',      'emergency',      'important',      'immediately',      'critical',      'right now',      'now'    ];    return urgentPatterns.any((p) => text.contains(p));  }  bool _isQuestion(String text) {    return text.contains('?') ||        text.startsWith('what') ||        text.startsWith('where') ||        text.startsWith('when') ||        text.startsWith('who') ||        text.startsWith('how') ||        text.startsWith('why') ||        text.startsWith('can you') ||        text.startsWith('could you');  }  bool _isGreeting(String text) {    final greetings = [      'hi',      'hello',      'hey',      'good morning',      'good afternoon',      'good evening'    ];    return greetings.any((g) => text.contains(g));  }  bool _isThanks(String text) {    return text.contains('thank') ||        text.contains('thanks') ||        text.contains('appreciate');  }  bool _isAffirmative(String text) {    return text.contains('yes') ||        text.contains('sure') ||        text.contains('okay') ||        text.contains('ok') ||        text.contains('agree');  }  bool _isNegative(String text) {    return text.contains('no ') ||        text.contains('not ') ||        text.contains('never') ||        text.contains('can\'t') ||        text.contains('won\'t');  }  bool _isEmergency(String text) {    final patterns = [      'sos',      'help',      'emergency',      'danger',      '救命',      'спас',      'निकासी'    ];    return patterns.any((p) => text.contains(p));  }  String suggestReply(String message) {    final category = classifyMessage(message);    final replies = _autoReplies[category] ?? _autoReplies['ok']!;    return replies[_random.nextInt(replies.length)];  }  List<String> getSuggestedReplies(String message, {int count = 3}) {    final category = classifyMessage(message);    final replies = _autoReplies[category] ?? _autoReplies['ok']!;    final shuffled = List<String>.from(replies)..shuffle(_random);    return shuffled.take(count).toList();  }  List<String> extractKeywords(String text, {int maxKeywords = 5}) {    final words = text.toLowerCase().split(RegExp(r'\W+'));    final keywords = <String>[];    final seen = <String>{};    for (final word in words) {      if (word.length < 3) continue;      if (seen.contains(word)) continue;      for (final entry in _keywords.entries) {        if (entry.value.any((kw) => word.contains(kw) || kw.contains(word))) {          if (!keywords.contains(entry.key)) {            keywords.add(entry.key);            seen.add(word);            break;          }        }      }    }    return keywords.take(maxKeywords).toList();  }  String summarizeText(String text, {int maxLength = 50}) {    if (text.length <= maxLength) return text;    final sentences = text.split(RegExp(r'[.!?]+'));    if (sentences.isEmpty) return text.substring(0, maxLength);    final firstSentence = sentences.first.trim();    if (firstSentence.length <= maxLength) return firstSentence;    final words = firstSentence.split(' ');    final summary = StringBuffer();    for (final word in words) {      if (summary.length + word.length + 1 > maxLength) break;      if (summary.isNotEmpty) summary.write(' ');      summary.write(word);    }    return '${summary.toString()}...';  }  String generateAIResponse(String userMessage) {    final category = classifyMessage(userMessage);    final keywords = extractKeywords(userMessage);    switch (category) {      case 'urgent':        return 'I understand this is urgent. Let me help you right away. '            'What\'s the most critical issue?';      case 'question':        final kw = keywords.isNotEmpty ? keywords.first : 'topic';        return 'Good question about $kw! '            'Based on available information: ';      case 'greeting':        return 'Hello! I\'m your offline AI assistant. '            'I can help with message suggestions, location sharing, '            'and safety features. How can I assist you today?';      case 'thanks':        return 'You\'re welcome! Is there anything else I can help with?';      case 'emergency':        return '🚨 EMERGENCY MODE ACTIVATED\n\n'            'Initiating SOS protocol:\n'            '1. Broadcasting location to Circle\n'            '2. Alerting trusted contacts\n'            '3. Recording audio\n\n'            'Stay calm. Help is on the way.';      case 'thanks':        return 'Happy to help! Let me know if you need anything else.';      default:        if (keywords.isNotEmpty) {          return 'I detected keywords: ${keywords.join(", ")}. '              'Would you like me to:\n'              '• Send this as an SOS\n'              '• Search related information\n'              '• Share your location\n'              '• Suggest auto-replies';        }        return 'I\'m here to help! I can:\n'            '• Suggest auto-replies to messages\n'            '• Categorize messages as urgent/normal\n'            '• Extract keywords from text\n'            '• Summarize long messages\n'            '• Help with safety features';    }  }  String expandAcronym(String acronym) {    final expansions = {      'lol': 'Laugh Out Loud',      'lmao': 'Laughing My A** Off',      'brb': 'Be Right Back',      'btw': 'By The Way',      'idk': 'I Don\'t Know',      'imo': 'In My Opinion',      'imho': 'In My Humble Opinion',      'omg': 'Oh My God',      'wtf': 'What The F***',      'faq': 'Frequently Asked Questions',      'sos': 'Save Our Souls / Emergency Signal',      'eta': 'Estimated Time of Arrival',      'fyi': 'For Your Information',      'asap': 'As Soon As Possible',      'aka': 'Also Known As',      'nvm': 'Never Mind',      'rn': 'Right Now',      'tbh': 'To Be Honest',      'ty': 'Thank You',      'yw': 'You\'re Welcome',    };    return expansions[acronym.toLowerCase()] ?? 'Unknown acronym';  }  int detectSentiment(String text) {    final lower = text.toLowerCase();    int score = 0;    final positiveWords = [      'happy',      'great',      'good',      'love',      'excellent',      'awesome',      'amazing',      'wonderful',      'fantastic'    ];    final negativeWords = [      'sad',      'bad',      'terrible',      'awful',      'hate',      'angry',      'frustrated',      'annoyed',      'worried'    ];    final urgentWords = [      'urgent',      'emergency',      'critical',      'important',      'asap',      'now',      'help'    ];    for (final word in positiveWords) {      if (lower.contains(word)) score += 1;    }    for (final word in negativeWords) {      if (lower.contains(word)) score -= 1;    }    for (final word in urgentWords) {      if (lower.contains(word)) score -= 2;    }    return score.clamp(-3, 3);  }  String getSentimentEmoji(int sentiment) {    if (sentiment >= 2) return '😊 Positive';    if (sentiment >= 1) return '🙂 Slightly Positive';    if (sentiment <= -2) return '😟 Negative';    if (sentiment <= -1) return '😐 Slightly Negative';    return '😐 Neutral';  }  String generateCheckInResponse(String status) {    final sentiment = detectSentiment(status);    final keywords = extractKeywords(status);    if (keywords.contains('medical')) {      return '⚠️ Medical concern detected. Sending wellness check to your Circle.';    }    if (keywords.contains('safety')) {      return '🚨 Safety concern flagged. Sharing location with trusted contacts.';    }    if (sentiment >= 1) {      return '👍 Great to hear! Your Circle has been notified of your status.';    }    if (sentiment <= -1) {      return '🤝 Hope everything is okay. Your Circle has been notified. Reach out if you need support.';    }    return '✅ Check-in received. Your Circle knows you\'re ${keywords.isNotEmpty ? keywords.first : "checked in"}.';  }}